      hu: ["Az 1960-as években fejezték be.", "Yahya Merchant pakisztáni építész tervezte.", "Fehér márvánnyal burkolva."],
      ro: ["Finalizat în anii 1960.", "Proiectat de un arhitect pakistanez, Yahya Merchant.", "Îmbrăcat în marmură albă."],
