      ro: "Moscheea națională a Pakistanului, situată în Islamabad. Designul său contemporan, inspirat de un cort beduin, este un punct de reper al orașului.",
      en: "The national mosque of Pakistan, located in Islamabad. Its contemporary design, inspired by a Bedouin tent, is a landmark of the city.",
      es: "La mezquita nacional de Pakistán en Islamabad. Su diseño moderno, inspirado en una tienda beduina, es un emblema de la ciudad.",
      pt: "A mesquita nacional do Paquistão em Islamabad. O seu design moderno, inspirado numa tenda beduína, é um marco da cidade.",
      fr: "La mosquée nationale du Pakistan à Islamabad. Son design moderne, inspiré d'une tente bédouine, est un symbole de la ville.",
